sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gate = new x_fed_day2_ops.EntraHelpdeskGate();
  var verdict = gate.preflight({ requester_id: 'day2-requester-sysid', approver_id: '', privileged: false });
  if (verdict.ok) { stepResult.setFailed('SoD indeterminate (no approver) passed - must fail closed'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var gate = new x_fed_day2_ops.EntraHelpdeskGate();
  var verdict = gate.preflight({ requester_id: '', approver_id: 'day2-approver-sysid', privileged: false });
  if (verdict.ok) { stepResult.setFailed('SoD indeterminate (no requester) passed - must fail closed'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
